package net.famzangl.minecraft.aimbow.aiming;
import net.famzangl.minecraft.aimbow.SmartAimConfig;
import net.minecraft.entity.Entity;
import net.minecraft.util.Vec3;
public final class SmartTargeting {private SmartTargeting(){}public static final class PredictionResult{public final Vec3 position;public final PredictionMode mode;public final float confidence;public PredictionResult(Vec3 p,PredictionMode m,float c){position=p;mode=m;confidence=c;}}
 public static PredictionResult[] predict(Entity target,Vec3 playerEyes,double speed){double distance=playerEyes.distanceTo(new Vec3(target.posX,target.posY,target.posZ));int ticks=(int)Math.ceil(distance/Math.max(.1,speed));ticks=Math.max(1,Math.min(ticks,60));return new PredictionResult[]{new PredictionResult(TargetSimulator.simulateJump(target,ticks),PredictionMode.PHYSICS,target.onGround?.3F:.9F),new PredictionResult(TargetSimulator.simulatePath(target,ticks),PredictionMode.PATH,TargetSimulator.isBridge(target)?.85F:.2F),new PredictionResult(TargetSimulator.simulateVector(target,ticks),PredictionMode.VECTOR,target.onGround&&!TargetSimulator.isBridge(target)?.75F:.4F),new PredictionResult(new Vec3(target.posX,target.posY,target.posZ),PredictionMode.STATIONARY,.25F)};}
 public static PredictionResult select(PredictionResult[] values,Vec3 eyes,Vec3 look){PredictionResult best=null;double score=-1;Vec3 gaze=look.normalize();for(PredictionResult p:values){Vec3 to=p.position.subtract(eyes);if(to.lengthVector()<1E-7)continue;double dot=Math.max(-1,Math.min(1,to.normalize().dotProduct(gaze))),angle=Math.acos(dot),s=p.confidence/(1+angle);if(s>score){score=s;best=p;}}return best;}
 public static Vec3 bias(Vec3 p,Entity t){double speed=Math.sqrt(t.motionX*t.motionX+t.motionZ*t.motionZ);return speed>.01?p.addVector(t.motionX/speed*SmartAimConfig.HITBOX_BIAS,0,t.motionZ/speed*SmartAimConfig.HITBOX_BIAS):p;}}
